-- =============================================================================
-- 491 — LE CAHIER D'EXERCICES DE 4E (partie 10)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/4e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 491 --niveau 4e --fichiers sport.jumelles,svt.jumelles-2 --suffixe 10 > supabase/contenu/491_exercices_4e_10.sql
--
-- 42 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   sport.jumelles          24 exercices · 8 chapitres
--   svt.jumelles-2          18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('2a4bc902-fa21-5678-9713-99776badd1da'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le règlement du tournoi","competence":"analyser-document","situation":"Avant le tournoi de la classe, le professeur affiche le règlement. Il demande à chacun de comprendre à quoi sert chaque règle.","documents":[{"id":"reglement","type":"fiche","modele":"affiche","entete":"Règlement du tournoi","emoji":"📜","lignes":[{"texte":"Un but vaut 1 point","id":"z1"},{"texte":"Un match dure 2 × 8 minutes","id":"z2"},{"texte":"Le terrain mesure 20 m sur 12 m","id":"z3"},{"texte":"Les contacts brutaux sont interdits","id":"z4"},{"texte":"Protège-tibias obligatoires","id":"z5"}],"pied":"Règlement écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux règles de sécurité.","aide":"Elles fixent les contacts autorisés ou le matériel obligatoire.","type":"zone","document":"reglement","multiple":true},{"enonce":"Range chaque règle dans sa famille.","aide":"Le terrain, les zones et la durée sont des règles d’espace et de temps.","type":"categories","categories":[{"id":"c0","texte":"But"},{"id":"c1","texte":"Espace et temps"},{"id":"c2","texte":"Sécurité"}],"items":[{"id":"i0","texte":"Un match dure 2 × 8 minutes"},{"id":"i1","texte":"Un but vaut 1 point"},{"id":"i2","texte":"Le terrain mesure 20 m sur 12 m"},{"id":"i3","texte":"Protège-tibias obligatoires"}]},{"enonce":"À quoi sert la règle dans un sport ?","aide":"Sans règle commune, il n’y a pas de match.","type":"choix","options":[{"id":"a","texte":"Elle empêche de jouer"},{"id":"b","texte":"Elle ne sert à rien sans arbitre"},{"id":"c","texte":"Elle crée le jeu en fixant ce qui compte"},{"id":"d","texte":"Elle sert seulement à punir"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4","z5"]},"explication":"L’interdiction des **contacts brutaux** et les **protège-tibias** protègent les joueurs : ce sont les règles de sécurité."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c2"}},"explication":"**But** : comment on marque. **Espace et temps** : durée et terrain. **Sécurité** : contacts et matériel."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sans règle commune, il n’y a pas de match : la règle **crée le jeu**."}]$ex$::jsonb),
  ('2a4bc902-fa21-5678-9713-99776badd1da'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le match de Lilou","competence":"analyser-texte","situation":"Lilou vient de jouer la finale du tournoi de basket. Son équipe a gagné largement. Elle raconte trois moments du match à son professeur.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le récit de Lilou","auteur":"Texte écrit pour l’exercice","blocs":["Mon équipe menait de dix points. Un adversaire est tombé et je lui ai tendu la main pour le relever.","Plus tard, le ballon a touché mon pied avant de sortir. L’arbitre n’a rien vu et a donné la remise à mon équipe, mais j’ai levé la main et j’ai avoué ma faute.","À la fin du match, je n’ai pas ri des perdants : j’ai serré la main de chacun."]}],"questions":[{"enonce":"Touche le mot qui montre que Lilou reconnaît une faute que l’arbitre n’a pas vue.","aide":"C’est un verbe du deuxième paragraphe.","type":"zone","document":"recit","multiple":false},{"enonce":"Relie chaque situation au geste de fair-play.","aide":"Relis les trois moments du récit.","type":"association","gauche":[{"id":"g0","texte":"L’arbitre n’a pas vu une faute"},{"id":"g1","texte":"Un joueur est à terre"},{"id":"g2","texte":"L’adversaire est dominé"},{"id":"g3","texte":"Le match est fini"}],"droite":[{"id":"d0","texte":"L’aider"},{"id":"d1","texte":"Serrer la main"},{"id":"d2","texte":"Ne pas l’humilier"},{"id":"d3","texte":"La reconnaître"}]},{"enonce":"Lilou avoue alors que l’arbitre n’a rien vu. Comment appeler son geste ?","aide":"Le fair-play commence là où finit la surveillance.","type":"choix","options":[{"id":"a","texte":"Une triche déguisée pour séduire l’arbitre"},{"id":"b","texte":"Du fair-play, même sans témoin"},{"id":"c","texte":"De la naïveté, car personne n’avait vu"},{"id":"d","texte":"De l’obéissance à l’arbitre qui regarde"}],"multiple":false},{"enonce":"Complète la phrase sur gagner et perdre.","aide":"Le premier verbe concerne l’adversaire battu, le second les excuses.","type":"trous","segments":["Gagner sans ",0,", perdre sans ",1,"."],"banque":["serrer","jouer","mépriser","accuser"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m54"]},"explication":"**Avouer** une faute que personne n’a vue, c’est du fair-play."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"Reconnaître la faute, **aider** celui qui est à terre, ne pas **humilier** et serrer la main : quatre gestes de fair-play."},{"cle":{"type":"choix","ids":["b"]},"explication":"Respecter la règle quand l’arbitre regarde, c’est de l’**obéissance** ; quand il ne regarde pas, c’est du **fair-play**."},{"cle":{"type":"trous","trous":[["mepriser"],["accuser"]]},"affichage":"mépriser · accuser","explication":"On gagne **sans mépriser** et on perd **sans accuser** : c’est ce qui permet de voir ce qu’il y avait à corriger."}]$ex$::jsonb),
  ('2a4bc902-fa21-5678-9713-99776badd1da'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un titre annulé, un tournoi à relire","competence":"argumenter","situation":"Un club a annulé un titre départemental pour dopage. Quelques semaines plus tard, trois équipes de ta classe jouent un tournoi. Tu relis les deux situations avec les valeurs olympiques.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Titre annulé","auteur":"Article imaginé pour l’exercice","blocs":["Le titre de Camille est annulé : un contrôle a révélé un produit interdit dans son organisme.","Elle est exclue des compétitions. Son médecin rappelle que ces produits agissent sur le cœur, les hormones et le psychisme."]},{"id":"tournoi","type":"tableau","titre":"Le tournoi de la classe","colonnes":["Équipe","Score","Comportement après le match"],"lignes":[["Rouge","12-2","Se moque des perdants"],["Bleue","2-12","Accuse l’arbitre"],["Verte","8-6","Serre la main de tous"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Pourquoi le dopage est-il interdit ?","aide":"L’article cite les organes touchés.","type":"choix","options":[{"id":"a","texte":"Il n’est interdit qu’aux sportifs adultes"},{"id":"b","texte":"Il fait perdre trop de temps aux arbitres"},{"id":"c","texte":"Il fausse la compétition et met la santé en danger"},{"id":"d","texte":"Il rend le sport trop facile à regarder en direct"}],"multiple":false},{"enonce":"Que prouve une victoire obtenue en trichant ?","aide":"Pense à ce que la victoire doit mesurer.","type":"choix","options":[{"id":"a","texte":"Que l’arbitre est trop faible pour sanctionner"},{"id":"b","texte":"Rien, pas même à celui qui triche"},{"id":"c","texte":"Que la règle du jeu est mauvaise"},{"id":"d","texte":"Que l’on est vraiment le meilleur joueur"}],"multiple":false},{"enonce":"Touche le comportement de l’équipe qui cherche une excuse après sa défaite.","aide":"Elle blâme quelqu’un d’autre que son équipe.","type":"zone","document":"tournoi","multiple":false},{"enonce":"Range chaque comportement.","aide":"Pense aux gestes de gagner sans mépriser et perdre sans accuser.","type":"categories","categories":[{"id":"c0","texte":"Fair-play"},{"id":"c1","texte":"Pas de fair-play"}],"items":[{"id":"i0","texte":"Se moquer des perdants"},{"id":"i1","texte":"Aider un adversaire à terre"},{"id":"i2","texte":"Serrer la main de tous"},{"id":"i3","texte":"Accuser l’arbitre"}]},{"enonce":"Relie chaque valeur olympique à ce qu’elle demande.","aide":"Les trois valeurs sont excellence, amitié, respect.","type":"association","gauche":[{"id":"g0","texte":"Excellence"},{"id":"g1","texte":"Amitié"},{"id":"g2","texte":"Respect"}],"droite":[{"id":"d0","texte":"De la règle, de l’adversaire, de soi"},{"id":"d1","texte":"Placer le lien avant le résultat"},{"id":"d2","texte":"Donner son meilleur"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Le dopage **fausse la compétition** et **met la santé en danger** : cœur, hormones, psychisme."},{"cle":{"type":"choix","ids":["b"]},"explication":"Une victoire obtenue en trichant **ne prouve rien**, pas même à celui qui triche."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"L’équipe Bleue **accuse l’arbitre** : le mauvais perdant se prive de ce qu’il y avait à corriger."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Serrer la main et aider un adversaire sont des gestes de **fair-play** ; se moquer ou accuser en sont l’inverse."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**Excellence** : donner son meilleur. **Amitié** : le lien avant le résultat. **Respect** : de la règle, de l’adversaire, de soi."}]$ex$::jsonb),
  ('3dde2d1b-5ad2-597b-a257-6bb73c39a4a6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les nuits de Camille","competence":"se-reperer-temps","situation":"Camille a un cross demain matin. Elle se couche à l’heure indiquée par la première horloge et son réveil sonne à l’heure de la seconde.","documents":[{"id":"coucher","type":"horloge","titre":"Heure du coucher","heures":21,"minutes":30,"numerique":true},{"id":"lever","type":"horloge","titre":"Heure du réveil","heures":7,"minutes":0,"numerique":true}],"questions":[{"enonce":"Combien d’heures Camille dort-elle, si elle s’endort tout de suite ?","aide":"De 21 h 30 à minuit, puis de minuit à 7 h.","type":"nombre","unite":"h"},{"enonce":"Camille respecte-t-elle le besoin de sommeil d’un adolescent ?","aide":"Compare sa durée de sommeil à la fourchette du cours.","type":"choix","options":[{"id":"a","texte":"Oui : elle est dans la fourchette de 8 à 10 h"},{"id":"b","texte":"Non : elle dort moins de 8 heures par nuit"},{"id":"c","texte":"Non : elle dort plus de 10 heures par nuit"},{"id":"d","texte":"On ne peut pas savoir sans connaître son âge"}],"multiple":false},{"enonce":"Complète le repère.","aide":"C’est la fourchette utilisée dans la question précédente.","type":"trous","segments":["Un adolescent a besoin de ",0," à ",1," heures de sommeil par nuit."],"banque":["8","5","12","10"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":9.5,"tolerance":0},"affichage":"9,5 h","explication":"De 21 h 30 à minuit : 2 h 30 ; de minuit à 7 h : 7 h. Au total **9 h 30**, soit 9,5 heures."},{"cle":{"type":"choix","ids":["a"]},"explication":"9 h 30 est entre 8 et 10 heures : **oui**, c’est le bon repère pour un adolescent."},{"cle":{"type":"trous","trous":[["8","huit"],["10","dix"]]},"affichage":"8 · 10","explication":"Le besoin d’un adolescent est de **8 à 10 heures** par nuit."}]$ex$::jsonb),
  ('3dde2d1b-5ad2-597b-a257-6bb73c39a4a6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le plateau-repas du sportif","competence":"analyser-document","situation":"Karim a cours d’EPS à 14 h et le menu de la cantine est affiché. Il veut choisir ce qui lui donnera de l’énergie et réparera ses muscles, mais il n’a pas pris de petit-déjeuner.","documents":[{"id":"menu","type":"fiche","modele":"menu","entete":"Cantine du collège","sousTitre":"Menu du jour","emoji":"🍽️","lignes":[{"texte":"Carottes râpées","id":"z1"},{"texte":"Poulet rôti","id":"z2"},{"texte":"Riz","id":"z3"},{"texte":"Pomme","id":"z4"},{"texte":"Eau","id":"z5"}],"pied":"Menu écrit pour l’exercice"}],"questions":[{"enonce":"Touche le plat qui apporte surtout le carburant de l’effort (glucides complexes).","aide":"Pâtes, riz, pain, légumes secs sont des glucides complexes.","type":"zone","document":"menu","multiple":false},{"enonce":"Touche le plat qui aide à réparer le muscle (protéines).","aide":"Viande, poisson, œufs et légumineuses sont riches en protéines.","type":"zone","document":"menu","multiple":false},{"enonce":"Range chaque aliment selon son apport principal.","aide":"Les compléments protéinés sont inutiles pour un adolescent qui mange varié.","type":"categories","categories":[{"id":"c0","texte":"Glucides complexes"},{"id":"c1","texte":"Protéines"},{"id":"c2","texte":"Fruits et légumes"},{"id":"c3","texte":"Inutile à cet âge"}],"items":[{"id":"i0","texte":"Lentilles"},{"id":"i1","texte":"Pâtes"},{"id":"i2","texte":"Haricots verts"},{"id":"i3","texte":"Pomme"},{"id":"i4","texte":"Œufs"},{"id":"i5","texte":"Complément protéiné"}]},{"enonce":"Que risque Karim en venant à l’EPS sans avoir pris de petit-déjeuner ?","aide":"Pense à ce que le cours dit de l’EPS à jeun.","type":"choix","options":[{"id":"a","texte":"Un malaise"},{"id":"b","texte":"Aucun risque"},{"id":"c","texte":"Une entorse"},{"id":"d","texte":"Un claquage assuré"}],"multiple":false}]}$ex$::jsonb,
