  ('3dde2d1b-5ad2-597b-a257-6bb73c39a4a6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les 60 minutes d’Adam","competence":"raisonner","situation":"L’OMS recommande aux 5-17 ans au moins 60 minutes d’activité physique par jour. Adam a noté sa journée et il se couche tard après avoir regardé son téléphone. Il se demande ce que cela change.","documents":[{"id":"journee","type":"tableau","titre":"La journée d’Adam (activité physique)","colonnes":["Moment","Activité","Durée (min)"],"lignes":[["Matin","Vélo jusqu’au collège",15],["Midi","Escaliers et récréation",15],["Après-midi","Cours d’EPS",30],["Soir","Promener le chien",10]],"enteteLignes":true,"source":"Journée écrite pour l’exercice"},{"id":"ecran","type":"chaine","disposition":"colonne","noeuds":[{"id":"z1","texte":"Écran tard le soir","emoji":"📱"},{"id":"z2","texte":"Lumière bleue","emoji":"💡"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Endormissement décalé","emoji":"😴"},{"id":"z5","texte":"Nuit raccourcie","emoji":"⏰"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Combien de minutes d’activité physique Adam a-t-il faites dans la journée ?","aide":"Additionne les quatre durées du tableau.","type":"nombre","unite":"min"},{"enonce":"Adam atteint-il la recommandation de l’OMS ?","aide":"Marcher, prendre l’escalier et faire du vélo comptent aussi.","type":"choix","options":[{"id":"a","texte":"Oui : 70 minutes dépassent les 60 minutes"},{"id":"b","texte":"Non : seul le sport encadré est comptabilisé"},{"id":"c","texte":"Non : l’EPS ne compte pas dans le total"},{"id":"d","texte":"Non : il lui manque encore 10 minutes"}],"multiple":false},{"enonce":"Dans la chaîne, la lumière bleue retarde la sécrétion de quelle hormone ?","aide":"C’est l’hormone du sommeil.","type":"texte","placeholder":"Une hormone"},{"enonce":"Adam fait de l’EPS mais passe cinq heures assis chaque jour. Que dire de la sédentarité ?","aide":"On peut faire du sport et être sédentaire le reste du temps.","type":"choix","options":[{"id":"a","texte":"C’est un risque distinct qu’une séance ne compense pas"},{"id":"b","texte":"Elle ne concerne que les adultes sédentaires"},{"id":"c","texte":"Elle est sans danger pour la santé"},{"id":"d","texte":"Une séance d’EPS suffit à la compenser"}],"multiple":false}]}$ex$::jsonb,
